using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterCallbackReceiverTests
{
    [Fact]
    public async Task ExplicitCallbackReceiverImplementationCompiles()
    {
        string testSource = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace TestNs
            {
                public class MyObject : IMessagePackSerializationCallbackReceiver
                {
                    public int Value { get; set; }

                    void IMessagePackSerializationCallbackReceiver.OnBeforeSerialize()
                    {
                    }

                    void IMessagePackSerializationCallbackReceiver.OnAfterDeserialize()
                    {
                    }
                }

                [GeneratedMessagePackFormatter]
                public partial class MyObjectFormatter : IMessagePackFormatter<MyObject>
                {
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver
                {
                }
            }
            """;

        var test = new VerifyCS.Test()
        {
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        test.TestState.Sources.Add(testSource);
        await test.RunAsync();
    }
}
